--
ALTER TABLE clientes
ADD CONSTRAINT fk_clientes_tipos_documento FOREIGN KEY (id_tipo_documento)
REFERENCES tipos_documento (id_tipo_documento) ON UPDATE CASCADE;

DELIMITER $$

--
-- Create procedure `sp_tipos_documento_verificar_dependencias`
--
CREATE
DEFINER = 'miguel'@'localhost'
PROCEDURE IF NOT EXISTS sp_tipos_documento_verificar_dependencias (IN p_id_tipo_documento int)
BEGIN
  SELECT
    COUNT(id_cliente) AS count
  FROM clientes
  WHERE id_tipo_documento = p_id_tipo_documento;
END
$$

--
-- Create procedure `sp_clientes_obtener_por_id`
--
CREATE
DEFINER = 'miguel'@'localhost'
PROCEDURE IF NOT EXISTS sp_clientes_obtener_por_id (IN p_id_cliente int)
BEGIN
  SELECT
    id_cliente,
    id_tipo_documento,
    numero_documento,
    nombres,
    apellidos,
    email,
    telefono,
    codigo_erp
  FROM clientes
  WHERE id_cliente = p_id_cliente;
END
$$

--
-- Create procedure `sp_clientes_listar`
--
CREATE
DEFINER = 'miguel'@'localhost'
PROCEDURE IF NOT EXISTS sp_clientes_listar ()
BEGIN
  SELECT
    c.id_cliente,
    c.nombres,
    c.apellidos,
    td.descripcion AS tipo_documento,
    c.numero_documento,
    c.email,
    c.telefono
  FROM clientes c
    JOIN tipos_documento td
      ON c.id_tipo_documento = td.id_tipo_documento
  ORDER BY c.apellidos, c.nombres;
END
$$

--
-- Create procedure `sp_clientes_eliminar`
--
CREATE
DEFINER = 'miguel'@'localhost'
PROCEDURE IF NOT EXISTS sp_clientes_eliminar (IN p_id_cliente int)
BEGIN
  DELETE
    FROM clientes
  WHERE id_cliente = p_id_cliente;
END
$$

--
-- Create procedure `sp_clientes_crear`
--
CREATE
DEFINER = 'miguel'@'localhost'
PROCEDURE IF NOT EXISTS sp_clientes_crear (IN p_id_tipo_documento int,
IN p_numero_documento varchar(20),
IN p_nombres varchar(100),
IN p_apellidos varchar(100),
IN p_email varchar(100),
IN p_telefono varchar(20),
IN p_codigo_erp varchar(20))
BEGIN
  DECLARE cliente_existente int;

  SELECT
    COUNT(*) INTO cliente_existente
  FROM clientes
  WHERE id_tipo_documento = p_id_tipo_documento
  AND numero_documento = p_numero_documento;

  IF cliente_existente > 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Ya existe un cliente con el mismo tipo y número de documento.';
  ELSE
    INSERT INTO clientes (id_tipo_documento, numero_documento, nombres, apellidos, email, telefono, codigo_erp)
      VALUES (p_id_tipo_documento, p_numero_documento, p_nombres, p_apellidos, p_email, p_telefono, p_codigo_erp);
    SELECT
      LAST_INSERT_ID() AS id_cliente;
  END IF;
END
$$

--
-- Create procedure `sp_clientes_buscar`
--
CREATE
DEFINER = 'miguel'@'localhost'
PROCEDURE IF NOT EXISTS sp_clientes_buscar (IN p_termino varchar(100))
BEGIN
  SET @termino_busqueda = CONCAT('%', p_termino, '%');
  SELECT
    c.id_cliente,
    c.nombres,
    c.apellidos,
    td.descripcion AS tipo_documento,
    c.numero_documento,
    c.email,
    c.telefono
  FROM clientes c
    JOIN tipos_documento td
      ON c.id_tipo_documento = td.id_tipo_documento
  WHERE c.nombres LIKE @termino_busqueda
  OR c.apellidos LIKE @termino_busqueda
  OR c.numero_documento LIKE @termino_busqueda
  ORDER BY c.apellidos, c.nombres;
END
$$

--
-- Create procedure `sp_clientes_actualizar`
--
CREATE
DEFINER = 'miguel'@'localhost'
PROCEDURE IF NOT EXISTS sp_clientes_actualizar (IN p_id_cliente int,
IN p_id_tipo_documento int,
IN p_numero_documento varchar(20),
IN p_nombres varchar(100),
IN p_apellidos varchar(100),
IN p_email varchar(100),
IN p_telefono varchar(20),
IN p_codigo_erp varchar(20))
BEGIN
  DECLARE cliente_existente int;
  SELECT
    COUNT(*) INTO cliente_existente
  FROM clientes
  WHERE id_tipo_documento = p_id_tipo_documento
  AND numero_documento = p_numero_documento
  AND id_cliente != p_id_cliente;

  IF cliente_existente > 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'El nuevo número de documento ya está en uso por otro cliente.';
  ELSE
    UPDATE clientes
    SET id_tipo_documento = p_id_tipo_documento,
        numero_documento = p_numero_documento,
        nombres = p_nombres,
        apellidos = p_apellidos,
        email = p_email,
        telefono = p_telefono,
        codigo_erp = p_codigo_erp
    WHERE id_cliente = p_id_cliente;
  END IF;
END
$$

--
-- Create procedure `sp_cliente_verificar_documento_existente`
--
CREATE
DEFINER = 'miguel'@'localhost'
PROCEDURE IF NOT EXISTS sp_cliente_verificar_documento_existente (IN p_numero_documento varchar(20),
IN p_id_cliente_excluir int)
BEGIN
  SELECT
    COUNT(id_cliente) AS `exists`
  FROM clientes
  WHERE numero_documento = p_numero_documento
  AND (p_id_cliente_excluir IS NULL
  OR id_cliente != p_id_cliente_excluir);
END
$$

DELIMITER ;

