    VALUES (p_id_tipo_curso, p_nombre, p_descripcion, p_codigo_erp);
END
$$

--
-- Create procedure `sp_cursos_buscar`
--
CREATE
DEFINER = 'miguel'@'localhost'
PROCEDURE IF NOT EXISTS sp_cursos_buscar (IN p_term varchar(100))
BEGIN
  SELECT
    c.id_curso,
    c.nombre,
    c.descripcion,
    c.codigo_erp,
    tc.nombre AS tipo_curso
  FROM cursos c
    JOIN tipos_curso tc
      ON c.id_tipo_curso = tc.id_tipo_curso
  WHERE c.nombre LIKE CONCAT('%', p_term, '%')
  OR c.descripcion LIKE CONCAT('%', p_term, '%')
  OR c.codigo_erp LIKE CONCAT('%', p_term, '%')
  ORDER BY c.nombre;
END
$$

--
-- Create procedure `sp_cursos_actualizar`
--
CREATE
DEFINER = 'miguel'@'localhost'
PROCEDURE IF NOT EXISTS sp_cursos_actualizar (IN p_id_curso int, IN p_id_tipo_curso int, IN p_nombre varchar(150), IN p_descripcion text, IN p_codigo_erp varchar(20))
BEGIN
  UPDATE cursos
  SET id_tipo_curso = p_id_tipo_curso,
      nombre = p_nombre,
      descripcion = p_descripcion,
      codigo_erp = p_codigo_erp
  WHERE id_curso = p_id_curso;
END
$$

