DELIMITER $$

--
-- Create procedure `sp_cursos_programados_por_profesor_en_rango`
--
CREATE
DEFINER = 'miguel'@'localhost'
PROCEDURE IF NOT EXISTS sp_cursos_programados_por_profesor_en_rango (IN p_id_profesor int,
IN p_fecha_inicio date,
IN p_fecha_fin date,
IN p_id_curso_programado_excluir int)
BEGIN
  SELECT
    cp.id_curso_programado,
    cp.fecha_inicio,
    cp.fecha_fin,
    cp.hora_inicio,
    cp.hora_fin,
    th.dias_semana
  FROM cursos_programados cp
    JOIN tipos_horario th
      ON cp.id_tipo_horario = th.id_tipo_horario
  WHERE cp.id_profesor = p_id_profesor
  AND cp.fecha_inicio <= p_fecha_fin
  AND cp.fecha_fin >= p_fecha_inicio
  AND (p_id_curso_programado_excluir IS NULL
  OR cp.id_curso_programado != p_id_curso_programado_excluir);
END
$$

--
-- Create procedure `sp_cursos_programados_obtener_por_id`
--
CREATE
DEFINER = 'miguel'@'localhost'
PROCEDURE IF NOT EXISTS sp_cursos_programados_obtener_por_id (IN p_id int)
BEGIN
  SELECT
    id_curso_programado,
    id_curso,
    id_profesor,
    id_sub_area,
    id_tipo_horario,
    fecha_inicio,
    fecha_fin,
    hora_inicio,
    hora_fin,
    vacantes_disponibles AS vacantes
  FROM cursos_programados
  WHERE id_curso_programado = p_id;
END
$$

--
-- Create procedure `sp_cursos_programados_listar`
--
CREATE
DEFINER = 'miguel'@'localhost'
PROCEDURE IF NOT EXISTS sp_cursos_programados_listar (IN p_id_profesor int,
IN p_id_curso int,
IN p_fecha_inicio date,
IN p_fecha_fin date)
BEGIN
  SELECT
    cp.id_curso_programado,
    c.nombre AS curso_nombre,
    CONCAT(p.nombres, ' ', p.apellidos) AS profesor_nombre,
    CONCAT(a.nombre, ' - ', sa.descripcion, ' ', sa.numero_sub_area) AS ubicacion,
    th.descripcion AS tipo_horario_nombre,
    cp.fecha_inicio,
    cp.fecha_fin,
    cp.hora_inicio,
    cp.hora_fin,
    cp.estado
  FROM cursos_programados cp
    JOIN cursos c
      ON cp.id_curso = c.id_curso
    JOIN profesores p
      ON cp.id_profesor = p.id_profesor
    JOIN tipos_horario th
      ON cp.id_tipo_horario = th.id_tipo_horario
    JOIN sub_areas sa
      ON cp.id_sub_area = sa.id_sub_area
    JOIN areas a
      ON sa.id_area = a.id_area
  WHERE (p_id_profesor IS NULL
  OR cp.id_profesor = p_id_profesor)
  AND (p_id_curso IS NULL
  OR cp.id_curso = p_id_curso)
  AND (p_fecha_inicio IS NULL
  OR cp.fecha_inicio >= p_fecha_inicio)
  AND (p_fecha_fin IS NULL
  OR cp.fecha_fin <= p_fecha_fin)
  ORDER BY cp.fecha_inicio DESC;
END
$$

--
-- Create procedure `sp_cursos_programados_crear`
--
CREATE
DEFINER = 'miguel'@'localhost'
PROCEDURE IF NOT EXISTS sp_cursos_programados_crear (IN p_id_curso int,
IN p_id_profesor int,
IN p_id_sub_area int,
IN p_id_tipo_horario int,
IN p_fecha_inicio date,
IN p_fecha_fin date,
IN p_hora_inicio time,
IN p_hora_fin time,
IN p_vacantes int)
BEGIN
  -- Obtenemos la capacidad de la sub-área para validar las vacantes
  DECLARE v_capacidad int;
  SELECT
    capacidad_maxima INTO v_capacidad
  FROM sub_areas
  WHERE id_sub_area = p_id_sub_area;

  IF p_vacantes > v_capacidad THEN
    SET p_vacantes = v_capacidad;
  END IF;

  INSERT INTO cursos_programados (id_curso, id_profesor, id_sub_area, id_tipo_horario, fecha_inicio, fecha_fin, hora_inicio, hora_fin, vacantes_disponibles)
    VALUES (p_id_curso, p_id_profesor, p_id_sub_area, p_id_tipo_horario, p_fecha_inicio, p_fecha_fin, p_hora_inicio, p_hora_fin, p_vacantes);

  SELECT
    LAST_INSERT_ID() AS id_curso_programado;
END
$$

--
-- Create procedure `sp_cursos_programados_actualizar`
--
CREATE
DEFINER = 'miguel'@'localhost'
PROCEDURE IF NOT EXISTS sp_cursos_programados_actualizar (IN p_id_curso_programado int,
IN p_id_curso int,
IN p_id_profesor int,
IN p_id_sub_area int,
IN p_id_tipo_horario int,
IN p_fecha_inicio date,
IN p_fecha_fin date,
IN p_hora_inicio time,
IN p_hora_fin time,
IN p_vacantes int)
BEGIN
  -- Se podría añadir lógica para no permitir la edición si el curso ya tiene matrículas,
  -- pero por ahora se mantiene simple.
  UPDATE cursos_programados
  SET id_curso = p_id_curso,
      id_profesor = p_id_profesor,
      id_sub_area = p_id_sub_area,
      id_tipo_horario = p_id_tipo_horario,
      fecha_inicio = p_fecha_inicio,
      fecha_fin = p_fecha_fin,
      hora_inicio = p_hora_inicio,
      hora_fin = p_hora_fin,
      vacantes_disponibles = p_vacantes
  WHERE id_curso_programado = p_id_curso_programado;
END
$$

--
-- Create procedure `sp_asistencia_profesor_obtener_detalle_curso`
--
CREATE
DEFINER = 'miguel'@'localhost'
PROCEDURE IF NOT EXISTS sp_asistencia_profesor_obtener_detalle_curso (IN p_id_curso_programado int)
BEGIN
  SELECT
