DELIMITER $$

--
-- Create procedure `sp_matricula_registrar_detalle`
--
CREATE
DEFINER = 'miguel'@'localhost'
PROCEDURE IF NOT EXISTS sp_matricula_registrar_detalle (IN p_id_matricula int,
IN p_id_curso_programado int,
IN p_id_cliente_asistencia int, -- Nuevo parámetro
IN p_precio_pactado decimal(10, 2),
IN p_descuento decimal(10, 2),
IN p_precio_final decimal(10, 2))
BEGIN
  DECLARE v_vacantes int;
  -- Verificar vacantes
  SELECT
    vacantes_disponibles INTO v_vacantes
  FROM cursos_programados
  WHERE id_curso_programado = p_id_curso_programado;
  IF v_vacantes > 0 THEN
    -- Insertar detalle
    INSERT INTO matriculas_detalle (id_matricula, id_curso_programado, id_cliente_asistencia, precio_pactado, descuento, precio_final)
      VALUES (p_id_matricula, p_id_curso_programado, p_id_cliente_asistencia, p_precio_pactado, p_descuento, p_precio_final);
    -- Actualizar vacantes
    UPDATE cursos_programados
    SET vacantes_disponibles = vacantes_disponibles - 1
    WHERE id_curso_programado = p_id_curso_programado;
    SELECT
      LAST_INSERT_ID() AS id_matricula_detalle;
  ELSE
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'No hay vacantes disponibles para este curso.';
  END IF;
END
$$

--
-- Create procedure `sp_dashboard_ventas_por_curso`
--
CREATE
DEFINER = 'miguel'@'localhost'
PROCEDURE IF NOT EXISTS sp_dashboard_ventas_por_curso (IN p_anio int,
IN p_mes int)
BEGIN
  SELECT
    c.nombre AS nombre_curso,
    SUM(md.precio_final) AS total_ventas
  FROM matriculas_detalle md
    JOIN matriculas m
      ON md.id_matricula = m.id_matricula
    JOIN cursos_programados cp
      ON md.id_curso_programado = cp.id_curso_programado
    JOIN cursos c
      ON cp.id_curso = c.id_curso
  WHERE YEAR(m.fecha_matricula) = p_anio
  AND MONTH(m.fecha_matricula) = p_mes
  GROUP BY c.nombre
  ORDER BY total_ventas DESC;
END
$$

