DELIMITER $$

--
-- Create procedure `sp_matricula_anular`
--
CREATE
DEFINER = 'miguel'@'localhost'
PROCEDURE IF NOT EXISTS sp_matricula_anular (IN p_id_matricula int,
IN p_observaciones text)
BEGIN
  DECLARE v_estado_actual varchar(20);

  -- Iniciar transacción
  START TRANSACTION;

    -- Verificar que la matrícula no esté ya anulada
    SELECT
      estado INTO v_estado_actual
    FROM matriculas
    WHERE id_matricula = p_id_matricula;

    IF v_estado_actual = 'Activa' THEN
      -- 1. Actualizar el estado de la matrícula y añadir la observación
      UPDATE matriculas
      SET estado = 'Anulada',
          observaciones = CONCAT(IFNULL(observaciones, ''), '\nANULACIÓN: ', p_observaciones)
      WHERE id_matricula = p_id_matricula;

      -- 2. Devolver las vacantes de los cursos asociados a esta matrícula
      UPDATE cursos_programados cp
      JOIN matriculas_detalle md
        ON cp.id_curso_programado = md.id_curso_programado
      SET cp.vacantes_disponibles = cp.vacantes_disponibles + 1
      WHERE md.id_matricula = p_id_matricula;

      -- 3. Opcional: Cambiar el estado de la asistencia del cliente a 'Cancelado'
      UPDATE asistencia_cliente ac
      JOIN matriculas_detalle md
        ON ac.id_matricula_detalle = md.id_matricula_detalle
      SET ac.estado = 'Cancelado'
      WHERE md.id_matricula = p_id_matricula;

      COMMIT;
    ELSE
      -- Si ya está anulada o completada, no hacer nada y revertir
      ROLLBACK;
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'La matrícula no se puede anular porque no está activa.';
    END IF;
END
$$

--
-- Create procedure `sp_asistencia_cliente_generar_cronograma`
--
CREATE
DEFINER = 'miguel'@'localhost'
PROCEDURE IF NOT EXISTS sp_asistencia_cliente_generar_cronograma (IN p_id_matricula_detalle int)
BEGIN
  DECLARE v_fecha_actual date;
  DECLARE v_fecha_fin date;
  DECLARE v_id_cliente int;
  DECLARE v_id_curso_programado int;
  DECLARE v_dias_semana varchar(20);

  -- Obtener datos de la programación y el cliente de asistencia
  SELECT
    cp.fecha_inicio,
    cp.fecha_fin,
    md.id_cliente_asistencia,
    cp.id_curso_programado,
    th.dias_semana INTO v_fecha_actual, v_fecha_fin, v_id_cliente, v_id_curso_programado, v_dias_semana
  FROM matriculas_detalle md
    JOIN cursos_programados cp
      ON md.id_curso_programado = cp.id_curso_programado
    JOIN tipos_horario th
      ON cp.id_tipo_horario = th.id_tipo_horario
  WHERE md.id_matricula_detalle = p_id_matricula_detalle;

  -- Solo generar si hay un cliente de asistencia asignado
  IF v_id_cliente IS NOT NULL THEN
    -- Limpiar cronograma existente por si se regenera
    DELETE
      FROM asistencia_cliente
    WHERE id_matricula_detalle = p_id_matricula_detalle;

    -- Bucle para generar registros de asistencia
    WHILE v_fecha_actual <= v_fecha_fin DO
      IF FIND_IN_SET(WEEKDAY(v_fecha_actual) + 1, v_dias_semana COLLATE utf8mb4_unicode_ci) THEN
        INSERT INTO asistencia_cliente (id_matricula_detalle, id_cliente, fecha_clase, estado)
          VALUES (p_id_matricula_detalle, v_id_cliente, v_fecha_actual, 'Programado');
      END IF;
      SET v_fecha_actual = DATE_ADD(v_fecha_actual, INTERVAL 1 DAY);
    END WHILE;
  END IF;
END
$$

DELIMITER ;

--
-- Create table `asistencia_profesor`
--
CREATE TABLE IF NOT EXISTS asistencia_profesor (
  id_asistencia_profesor int(11) NOT NULL AUTO_INCREMENT,
  id_curso_programado int(11) NOT NULL,
  id_profesor int(11) NOT NULL,
  fecha_clase date NOT NULL,
  estado enum ('Programado', 'Asistió', 'Faltó', 'Reprogramado') NOT NULL DEFAULT 'Programado',
  observaciones varchar(255) DEFAULT NULL,
  PRIMARY KEY (id_asistencia_profesor)
)
ENGINE = INNODB,
AUTO_INCREMENT = 328,
AVG_ROW_LENGTH = 315,
CHARACTER SET utf8mb4,
COLLATE utf8mb4_unicode_ci,
ROW_FORMAT = DYNAMIC;

