-- Create index `fk_precios_tipo_precio_idx` on table `lista_precios`
--
ALTER TABLE lista_precios
ADD INDEX fk_precios_tipo_precio_idx (id_tipo_precio);

--
-- Create foreign key
--
ALTER TABLE lista_precios
ADD CONSTRAINT fk_precios_curso FOREIGN KEY (id_curso)
REFERENCES cursos (id_curso);

--
-- Create foreign key
--
ALTER TABLE lista_precios
ADD CONSTRAINT fk_precios_tipo_precio FOREIGN KEY (id_tipo_precio)
REFERENCES tipos_precio (id_tipo_precio);

DELIMITER $$

--
-- Create procedure `sp_tipos_precio_verificar_dependencias`
--
CREATE
DEFINER = 'miguel'@'localhost'
PROCEDURE IF NOT EXISTS sp_tipos_precio_verificar_dependencias (IN p_id_tipo_precio int)
BEGIN
